window.updateAvailable=new Promise((resolve,reject)=>{if(!("serviceWorker"in navigator)){const errorMessage="This browser doesn't support service workers";console.error(errorMessage);reject(errorMessage);return}navigator.serviceWorker.register("/service-worker.min.js").then(registration=>{console.info(`Service worker registration successful (scope: ${registration.scope})`),setInterval(()=>{registration.update()},6e4),registration.onupdatefound=()=>{console.info(`Service worker onupdatefound event`);const installingServiceWorker=registration.installing;installingServiceWorker.onstatechange=()=>{installingServiceWorker.state==="installed"&&resolve(!!navigator.serviceWorker.controller)}}}).catch(error=>{console.error("Service worker registration failed with error:",error),reject(error)});navigator.serviceWorker.addEventListener("controllerchange",()=>{console.log("Service worker controller changed, reloading page"),window.location.reload(),resolve(!0)})});